        - "**/node_modules/**"
        - "**/target/**"
        - "**/out/**"
        - "**/.venv/**"
      run: npx --no-install dprint check {staged_files}
    - name: spelling
      glob:
        - "README.md"
        - "AGENTS.md"
        - "fonts/**/*.md"
        - "docs/**/*.md"
        - "tools/**/*.md"
        - "experiments/**/*.md"
      exclude:
        - "docs/references/VisualTrueType/**"
        - "docs/references/specs/**"
        - "docs/references/papers/*/paper.md"
        - "**/vendor/**"
        - "**/node_modules/**"
        - "**/target/**"
        - "**/out/**"
        - "**/.venv/**"
      run: npx --no-install cspell --no-progress --gitignore --no-must-find-files {staged_files}
    - name: rust-formatting
      glob:
        - "tools/generator/**/*.rs"
        - "tools/generator/Cargo.toml"
      exclude: "tools/generator/vendor/**"
      run: cargo fmt --manifest-path tools/generator/Cargo.toml --check

