import * as React from "react";
import { Button } from "../../../components/ui/button";
import capture from "./assets/rasterizers/capture.json";
import captureUrl from "./assets/rasterizers/capture.json?url";
import imagemagick from "./assets/rasterizers/imagemagick.png";
import lvgl from "./assets/rasterizers/lvgl.png";
import adafruit from "./assets/rasterizers/adafruit.png";
import fontforge from "./assets/rasterizers/fontforge.png";
import coretext from "./assets/rasterizers/coretext.png";
import repo from "./assets/rasterizers/repo.png";

const images: Record<string, string> = { imagemagick, lvgl, adafruit, fontforge, coretext, repo };

export function RasterizerComparison(): React.JSX.Element {
  const [zoom, setZoom] = React.useState(1);
  return (
    <section className="landing__comparison" aria-labelledby="rasterizer-comparison-title">
      <div className="landing__section-heading">
        <p className="landing__eyebrow">Captured output · 26 October 2026</p>
        <h2 id="rasterizer-comparison-title">Rasterizer comparison</h2>
        <p className="landing__section-intro">
          The same Roboto Regular instance at 16 pixels per em, rendered in monochrome by six tools.
          Each tool retains its own glyph advances and bearings, so differences include hinting,
          scan conversion and text placement. These samples cover one font and size; optical assessment remains open.
        </p>
      </div>
      <div className="landing__comparison-controls">
        <div role="group" aria-label="Comparison magnification" className="flex gap-1">
          {[1, 2, 4].map((value) => (
            <Button key={value} size="sm" variant={zoom === value ? "secondary" : "ghost"}
              aria-pressed={zoom === value} onClick={() => setZoom(value)}>{value}×</Button>
          ))}
        </div>
        <p>Shared crops, integer enlargement. Scroll horizontally to inspect wider samples.</p>
      </div>
      <div className="landing__comparison-grid" data-rasterizer-comparison data-expanded={zoom > 1}>
        {capture.samples.map((sample) => (
