import * as React from "react";
import { ArrowRight, BookOpen, Code2 } from "lucide-react";
import { NavLink } from "../../../components/NavLink";
import { Button } from "../../../components/ui/button";
import type { FontLibrary } from "../../fonts/useFontLibrary";
import { displayName } from "../../fonts/metadata";
import { FontCanvas } from "../../renderer/FontCanvas";
import { defaultVariantSettings } from "../../variants/model";
import { SiteHeader } from "../../shell/SiteHeader";
import { libraryPalette } from "../library/canvas-palettes";
import { RasterizerComparison } from "./RasterizerComparison";
import "./LandingPage.css";

const SOURCE = "https://github.com/ai212983/font_generator";

interface LandingPageProps {
  nav: React.ReactNode;
  fontsHref: string;
  onFonts: () => void;
  library: FontLibrary;
}

export function LandingPage({ nav, fontsHref, onFonts, library }: LandingPageProps): React.JSX.Element {
  const font = library.fonts?.find((item) => item.fileName === "Literata.ttf") ?? library.fonts?.[0];
  const settings = font ? defaultVariantSettings(font) : null;
  const { ensureLoaded } = library;
  const fontId = font?.id;
  React.useEffect(() => {
    if (fontId) ensureLoaded(fontId);
  }, [ensureLoaded, fontId]);
  const [renderError, setRenderError] = React.useState("");
  React.useEffect(() => setRenderError(""), [fontId]);
  const ready = Boolean(fontId && library.loadedIds.has(fontId));
  const pending = library.fonts === null && !library.bootError || Boolean(fontId && !ready);
  const unavailable = library.rendererAvailable === false || Boolean(renderError || (fontId && library.loadStatus(fontId).error));

  return (
    <div className="landing">
      <SiteHeader title="Glypherie" titleAs="div" variant="brand" nav={nav} displayControls={false} />
      <main id="main" className="landing__main" data-landing>
        <section className="landing__hero" aria-labelledby="landing-title">
          <div>
            <p className="landing__eyebrow">Bitmap font generation</p>
            <h1 id="landing-title">Bitmap fonts for<br /><span>low-resolution displays.</span></h1>
            <p className="landing__intro">
              Generate small bitmap fonts for monochrome and grayscale displays, including e-ink and reflective LCDs.
              Import a TrueType or OpenType font, set its size and variable axes, and inspect the rendered glyphs.
            </p>
            <div className="landing__actions">
              <Button asChild size="lg">
                <NavLink href={fontsHref} onNavigate={onFonts}>Open font library <ArrowRight aria-hidden="true" /></NavLink>
              </Button>
              <a href={`${SOURCE}#documentation`} className="landing__text-link"><BookOpen aria-hidden="true" />Documentation</a>
            </div>
            <p className="landing__note">Intended for text up to 48 px. Larger sizes are available.</p>
          </div>
          <figure className="landing__specimen" aria-label="Font specimen">
            <div className="landing__specimen-heading"><span>Live monochrome output</span><span aria-hidden="true">Aa / 01</span></div>
            <div className="landing__specimen-body">
              {font && settings && !unavailable ? (
                <FontCanvas
                  key={font.id}
                  fontId={font.id}
                  text={"Aa Bb\n012345"}
                  sizePx={24}
                  axes={settings.axes}
                  profile={settings.profile}
                  role={settings.renderer}
                  spacing={settings.letterSpacingPx}
                  kerning={settings.kerning}
                  stemFitting={settings.stemFitting}
                  diagonalFitting={settings.diagonalFitting}
                  monoRaster={settings.monoRaster}
                  rasterization="free_type_mono"
                  zoom={3}
                  mode="exact"
                  palette={libraryPalette("warm-paper", false)}
                  ready={ready}
                  debounceMs={0}
                  viewportProps={{ className: "landing__canvas", "aria-hidden": true }}
                  canvasProps={{ "data-landing-canvas": "", className: "block [image-rendering:pixelated]" }}
                  exposeFullHeight
                  clearOnError
                  onError={setRenderError}
                />
              ) : <span className="landing__type" aria-hidden="true">Aa</span>}
              {pending && !unavailable && <span className="landing__specimen-status">Preparing the live specimen…</span>}
            </div>
            <figcaption>
              <span>{font && !unavailable ? displayName(font) : "Font specimen unavailable"}</span>
              <span>{font && !unavailable ? "24 px · Monochrome · 3× view" : "Open the library to select a font"}</span>
            </figcaption>
          </figure>
        </section>

        <section className="landing__workflow" aria-labelledby="landing-start">
          <div className="landing__section-heading"><p className="landing__eyebrow">Workflow</p><h2 id="landing-start">Import, configure, export</h2></div>
          <ol className="landing__steps">
            <li><span className="landing__step-number">01</span><h3>Import a font</h3><p>Use a bundled font or import a .ttf or .otf file. Create a saved variant for each size and rendering configuration.</p></li>
            <li><span className="landing__step-number">02</span><h3>Configure rendering</h3><p>Set pixel size, variable axes, spacing and kerning. Inspect 1-bit monochrome output or a 2-, 3- or 4-bit grayscale palette.</p></li>
            <li><span className="landing__step-number">03</span><h3>Export and inspect</h3><p>Export monochrome variants as Playdate .fnt files. Check the result on the target display. For manual pixel editing, use a dedicated editor such as <a href="https://play.date/caps/">Playdate Caps</a> or <a href="https://github.com/kreativekorp/bitsnpicas">Bits’N’Picas</a>.</p></li>
          </ol>
        </section>

        <section className="landing__rendering" aria-labelledby="rendering-title">
          <div className="landing__section-heading"><p className="landing__eyebrow">Implementation</p><h2 id="rendering-title">Fitting and rasterization</h2></div>
          <p className="landing__section-intro">
            Fitting adjusts the outline to the pixel grid; scan conversion produces the bitmap.
            At small sizes, these stages affect stroke widths, joins, counters and spacing.
            Glypherie runs a Rust rendering pipeline compiled to WebAssembly in the browser.
          </p>
          <dl className="landing__pipeline">
            <div><dt>Monochrome</dt><dd>Skrifa hinting with project fitting extensions, followed by FreeType 1-bit scan conversion. Font hints and diagonal fitting can be enabled in the variant controls.</dd></div>
            <div><dt>Grayscale</dt><dd>Automatic fitting and coverage rasterization, quantized to 4, 8 or 16 levels using a saved palette preset.</dd></div>
            <div><dt>Export</dt><dd>Playdate .fnt output uses the monochrome variant settings. Grayscale export is currently unavailable.</dd></div>
          </dl>
          <a href={`${SOURCE}/blob/main/tools/generator/API.md#working-candidate-fitting`} className="landing__text-link">Rendering API and pipeline details <ArrowRight aria-hidden="true" /></a>
        </section>

        <RasterizerComparison />

        <section className="landing__details" aria-label="Storage and source">
          <div><h2>Browser-local storage</h2><p>Fonts, variants and palette presets are stored on this device in this browser. Font files are processed locally. A saved variant link requires the same local library; clearing site data removes it.</p></div>
          <div><h2>Source and documentation</h2><p>The repository contains the Rust generator, WebAssembly interface, browser app and fitting research. Glypherie provides generated bitmap output; per-glyph pixel editing is done in a separate bitmap font editor.</p><a href={SOURCE} className="landing__text-link"><Code2 aria-hidden="true" />Source on GitHub <ArrowRight aria-hidden="true" /></a></div>
        </section>
      </main>
    </div>
  );
}
