import * as React from "react";
import { useDisplayPreferences } from "../../shell/DisplayPreferences";
import { libraryFrame, libraryPalette } from "../library/canvas-palettes";
import { SpecimenFrame } from "../library/SpecimenFrame";
import capture from "./assets/rasterizers/capture.json";
import captureUrl from "./assets/rasterizers/capture.json?url";
import imagemagick from "./assets/rasterizers/imagemagick.png";
import lvgl from "./assets/rasterizers/lvgl.png";
import adafruit from "./assets/rasterizers/adafruit.png";
import fontforge from "./assets/rasterizers/fontforge.png";
import coretext from "./assets/rasterizers/coretext.png";
import repo from "./assets/rasterizers/repo.png";

const images: Record<string, string> = { imagemagick, lvgl, adafruit, fontforge, coretext, repo };

export function RasterizerComparison(): React.JSX.Element {
  const { zoom, canvas: { palette, inverse } } = useDisplayPreferences();
  const frame = libraryFrame(palette, inverse);
  const colors = libraryPalette(palette, inverse);
  const paper = colors[0]!;
  const ink = colors[1]!;
  const filterId = `landing-colors-${React.useId().replace(/:/g, "")}`;
  return (
    <section className="landing__comparison" aria-labelledby="rasterizer-comparison-title">
      <div className="landing__section-heading">
        <h2 id="rasterizer-comparison-title">Rasterizer comparison</h2>
        <p className="landing__section-intro">
          Compare six tools using the same font and text: Roboto Regular, 16 pixels per em, monochrome output.
        </p>
      </div>
      {/* Map source black/white to the shared ink/paper colors in sRGB, preserving pixel positions.
          https://drafts.csswg.org/filter-effects/#feComponentTransferElement */}
      <svg width="0" height="0" className="absolute pointer-events-none" aria-hidden="true" focusable="false">
        <defs>
          <filter id={filterId} colorInterpolationFilters="sRGB">
            <feComponentTransfer>
              <feFuncR type="table" tableValues={`${ink[0] / 255} ${paper[0] / 255}`} />
              <feFuncG type="table" tableValues={`${ink[1] / 255} ${paper[1] / 255}`} />
              <feFuncB type="table" tableValues={`${ink[2] / 255} ${paper[2] / 255}`} />
            </feComponentTransfer>
          </filter>
        </defs>
      </svg>
      <div className="landing__comparison-grid" data-rasterizer-comparison data-expanded={zoom > 1}>
        {capture.samples.map((sample) => (
          <figure key={sample.id} data-rasterizer={sample.id} className="landing__comparison-sample">
            <SpecimenFrame frame={frame} data-rasterizer-frame={sample.id}>
              <figcaption className="landing__preview-label">
                <h3 style={{ color: frame.inkCss }}><a href={sample.source_url}>{sample.label}</a></h3>
                <span style={{ color: frame.mutedCss }}>16 px / 1-bit</span>
              </figcaption>
            <div className="landing__comparison-scroll" role="region" aria-label={`${sample.label} sample`} tabIndex={0}>
              <div data-rasterizer-lines className="landing__comparison-lines"
                style={{ width: 468 * zoom, rowGap: capture.display_line_gap * zoom }}>
                {capture.display_lines.map((line, index) => (
                  <div key={line.top} className="landing__comparison-line" style={{ height: line.height * zoom }}>
                    <img src={images[sample.id]} width={468 * zoom} height={129 * zoom}
                      style={{ width: 468 * zoom, height: 129 * zoom, top: -line.top * zoom, filter: `url(#${filterId})` }}
                      alt={index === 0 ? `Roboto Regular, 16 px, monochrome output from ${sample.label}.` : ""} />
                  </div>
                ))}
              </div>
            </div>
            </SpecimenFrame>
          </figure>
        ))}
      </div>
      <details className="landing__capture-details">
        <summary>Comparison inputs and capture limits</summary>
        <p>Captured 26 October 2026. Each tool retains its own glyph advances and bearings, so differences include hinting, scan conversion and text placement. These samples cover one font and size; optical assessment remains open.</p>
        <dl className="landing__capture-sources">
          {capture.samples.map((sample) => <div key={sample.id}><dt>{sample.label}</dt><dd>{sample.note}</dd></div>)}
        </dl>
        <p>
          Static Roboto Regular, instantiated at <code>wght=400</code>, <code>wdth=100</code>.
          Pair kerning disabled; native advances preserved. All originals share a 1200 × 176 px canvas,
          one origin and three baselines. The source crops are 468 × 129 px. The preview omits rows
          that are blank in all six samples, placing the three lines 2 px apart at 1×.
          Every sample uses the same line windows. Display controls map black and white to the selected ink and paper colors;
          glyph coverage and horizontal placement are unchanged.
        </p>
        <pre>{capture.inputs.text}</pre>
        <p>
          The Glypherie image records a working source snapshot from the capture date and is independent of
          the live specimen below. Windows GDI was unavailable on the capture host. The truetype2gfx online
          preview uses antialiased text; the Adafruit monochrome conversion is identified separately here.
        </p>
        <a href={captureUrl} download="glypherie-rasterizer-capture.json">Download capture metadata and image hashes</a>
      </details>
    </section>
  );
}
