        for (let i = 0; i < data.length; i += 4) found.add(`${data[i]},${data[i + 1]},${data[i + 2]}`);
        return JSON.stringify([...found].sort()) === JSON.stringify(colors);
      }, expected);
      for (const sample of await page.locator("[data-rasterizer-lines]").all()) {
        // Inspect the actual composited screenshot: the PNG's raw pixels deliberately remain black/white.
