        const colors = await page.evaluate(async (base64) => {
          const image = new Image();
          image.src = `data:image/png;base64,${base64}`;
          await image.decode();
          const canvas = document.createElement("canvas");
          canvas.width = image.naturalWidth;
          canvas.height = image.naturalHeight;
          const context = canvas.getContext("2d")!;
          context.drawImage(image, 0, 0);
          const data = context.getImageData(0, 0, canvas.width, canvas.height).data;
          const found = new Set<string>();
          for (let i = 0; i < data.length; i += 4) found.add(`${data[i]},${data[i + 1]},${data[i + 2]}`);
          return [...found].sort();
        }, shot.toString("base64"));
        assert.deepEqual(colors, expected, `${preset.name}, inverse=${inverse}: captured preview uses the same ink and paper as the live renderer`);
      }
    }
  }
  const liveHeight = (await page.locator("[data-landing-canvas]").boundingBox())!.height;
  await setZoom(page, "3");
  assert.equal((await page.locator("[data-rasterizer-lines]").first().boundingBox())?.width, 1404, "3× is shared with captured previews");
  await page.waitForFunction((height) => document.querySelector("[data-landing-canvas]")!.getBoundingClientRect().height > height * 2, liveHeight);
  const styleOf = (element: Element) => {
